<script lang="ts">
  import type {Snippet} from 'svelte';
  import Icon from './Icon.svelte';
  import type {CanvasNode} from './profile-canvas';
  import type {SignalBundle} from './profile-signal-overview';
  import {processingSummary,PROCESSING_PRESETS} from './profile-processing';
  let {bundle,nodes,activeTransform=$bindable(''),close,transformSettings,insert,disconnect,readOnly=false,insertionPending=false}:
    {bundle?:SignalBundle;nodes:CanvasNode[];activeTransform?:string;close:()=>void;
      transformSettings?:Snippet<[CanvasNode]>;insert?:(id:string)=>void;disconnect?:(id:string)=>void;readOnly?:boolean;insertionPending?:boolean}=$props();
  let query=$state('');
  const byId=$derived(new Map(nodes.map(node=>[node.id,node])));
  const selected=$derived(byId.get(activeTransform));
  const lanes=$derived(bundle?.lanes.filter(lane=>[...lane.sources.map(source=>`${byId.get(source.nodeId)?.name} ${port(source.nodeId,source.portId)}`),port(lane.destination.nodeId,lane.destination.portId),...lane.transforms.map(id=>byId.get(id)?.name)].join(' ').toLowerCase().includes(query.toLowerCase()))??[]);
  const transforms=$derived(nodes.filter(node=>node.processing&&`${node.name} ${processingSummary(node.processing)}`.toLowerCase().includes(query.toLowerCase())));
  function port(id:string,portId:string){const node=byId.get(id);return [...(node?.resource?.ports??[]),...(node?.virtual?.ports??[]),...(node?.desktop?.ports??[])].find(port=>port.id===portId)?.name??portId;}
  function edit(id:string){activeTransform=activeTransform===id?'':id;}
  function label(node:CanvasNode){const operation=node.processing!.operation;const kind=operation.kind==='builtin'?operation.rule.kind:operation.kind;return PROCESSING_PRESETS.find(([preset])=>preset===kind)?.[1]??kind.replaceAll('-',' ');}
</script>

<!-- svelte-ignore a11y_no_noninteractive_element_interactions (Escape dismisses this region from its child controls.) -->
<section class="signal-lanes" aria-label="Signal lanes" onkeydown={event=>{if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close();}}}>
  <header>{#if bundle}<h3 class="source-device">{byId.get(bundle.binding.from.nodeId)?.name}</h3><span class="connection-direction"><Icon name="arrow" size={24}/></span><h3 class="destination-device">{byId.get(bundle.binding.to.nodeId)?.name}</h3>{:else}<h3>Transform settings</h3>{/if}</header>
  <div class="lane-toolbar"><input aria-label="Filter signal lanes" placeholder={bundle?'Find a signal or transform…':'Find a transform…'} bind:value={query}/>{#if query}<button class="text-button" aria-label="Clear signal lane search" onclick={()=>query=''}><Icon name="close" size={14}/></button>{/if}<span>{insertionPending?'Choose a signal’s + button to insert the dropped transform.':bundle?'Select a transform to edit it. Shared stages update every consumer.':'Includes shared stages and unfinished chains.'}</span></div>
  <div class="lane-scroll">
    {#if bundle}
      <div class="lane-head"><span>Source</span><span>Transform chain</span><span>Destination</span></div>
      {#each lanes as lane (lane.id)}
        <div class="signal-lane" data-lane-id={lane.id}>
          <div class="lane-endpoint">{#each lane.sources as source (`${source.nodeId}/${source.portId}`)}<strong>{port(source.nodeId,source.portId)}</strong>{/each}</div>
          <div class="lane-chain">{#each lane.transforms as id (id)}{@const node=byId.get(id)}{#if node?.processing}<button class="transform-chip" class:active={activeTransform===id} aria-pressed={activeTransform===id} data-transform-id={id} title={`${node.name} · ${processingSummary(node.processing)}`} onclick={()=>edit(id)}><strong>{label(node)}</strong><small>{processingSummary(node.processing)}</small>{#if node.processing.inputs.length>1}<em>Combined inputs</em>{/if}</button>{/if}{:else}<span class="direct">Direct</span>{/each}{#if insert}<button class="insert-transform" title="Add transform before destination" aria-label={`Add transform to ${port(lane.destination.nodeId,lane.destination.portId)}`} disabled={readOnly} onclick={()=>insert?.(lane.id)}><Icon name="plus" size={16}/></button>{/if}</div>
          <div class="lane-endpoint"><strong>{port(lane.destination.nodeId,lane.destination.portId)}</strong><div class="lane-actions">{#if disconnect}<button class="disconnect-route" aria-label={`Disconnect ${port(lane.destination.nodeId,lane.destination.portId)}`} title="Disconnect route" disabled={readOnly} onclick={()=>disconnect?.(lane.id)}><Icon name="unlink" size={16}/></button>{/if}</div></div>
        </div>
      {:else}<p class="empty">No matching signals.</p>{/each}
    {:else}<div class="transform-library">{#each transforms as node (node.id)}<button class="transform-chip" class:active={activeTransform===node.id} aria-pressed={activeTransform===node.id} data-transform-id={node.id} onclick={()=>edit(node.id)}><strong>{node.name}</strong><small>{node.processing?.draft?'Needs input · ':''}{processingSummary(node.processing!)}</small></button>{:else}<p>No matching transforms. Drop one from the component palette to start a chain.</p>{/each}</div>{/if}
  </div>
  {#if selected?.processing&&transformSettings}<div class="lane-settings" data-transform-settings={selected.id}><div><h4>{selected.name}</h4><p>Edits apply wherever this transform is used.</p></div><fieldset disabled={readOnly}>{@render transformSettings(selected)}</fieldset></div>{/if}
</section>

<style>
  .lane-chain .transform-chip{width:112px;max-width:112px;box-sizing:border-box;padding:8px}.lane-chain .transform-chip small{display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.lane-head,.signal-lane{grid-template-columns:minmax(110px,.8fr) minmax(280px,2.5fr) minmax(130px,.9fr)}
  .signal-lanes{background:var(--surface)}.signal-lanes header{position:sticky;top:0;z-index:2;background:var(--surface);display:grid;grid-template-columns:minmax(0,1fr) 40px minmax(0,1fr);align-items:center;gap:16px;padding:16px 20px;border-bottom:1px solid var(--line)}.connection-direction{display:grid;place-items:center;color:var(--accent)}.destination-device{text-align:right}h3,h4{margin:3px 0;font-size:15px}small{color:var(--muted);font-size:12px}.lane-toolbar{padding:12px 20px;display:flex;align-items:center;gap:10px}.lane-toolbar input{background:var(--input-bg);border:1px solid var(--line);border-radius:5px;color:var(--text);padding:8px 10px;width:240px;max-width:50%}.lane-toolbar>span{color:var(--muted);font-size:12px;margin-left:auto}.lane-scroll{max-height:340px;overflow:auto}.lane-head,.signal-lane{display:grid;grid-template-columns:minmax(150px,1fr) minmax(260px,2.5fr) minmax(170px,1fr);gap:20px;padding:14px 20px}.lane-head{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);border-bottom:1px solid var(--line)}.signal-lane{align-items:center;border-bottom:1px solid var(--line)}.lane-endpoint{display:flex;flex-direction:column;gap:5px;min-width:0}.lane-endpoint strong{font-size:13px;overflow-wrap:anywhere}.lane-chain,.transform-library{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.transform-chip{background:color-mix(in srgb,#9b80d8 14%,var(--surface));border:1px solid color-mix(in srgb,#9b80d8 40%,var(--line));color:var(--text);border-radius:5px;padding:9px 12px;display:flex;flex-direction:column;gap:5px;max-width:220px;text-align:left;cursor:pointer}.transform-chip strong{font-size:12px}.transform-chip small{font-size:11px;color:var(--soft);overflow-wrap:anywhere}.transform-chip em{font-size:10px;color:var(--muted)}.transform-chip.active,.transform-chip:hover{border-color:#bfa1ff;background:color-mix(in srgb,#9b80d8 24%,var(--surface))}.insert-transform{background:transparent;border:1px dashed var(--line);color:var(--accent);border-radius:5px;min-height:34px;cursor:pointer}.direct{color:var(--muted);font-size:12px;font-style:italic}.lane-endpoint:has(.lane-actions){display:grid;grid-template-columns:minmax(0,1fr) 28px;align-items:center}.lane-actions{display:flex;gap:12px}.disconnect-route{display:grid;place-items:center;width:28px;height:28px;border:0;border-radius:4px;background:transparent;color:var(--muted);cursor:pointer}.disconnect-route:hover:enabled{background:var(--surface-raised);color:var(--text)}.disconnect-route:focus-visible{outline:2px solid var(--accent)}.disconnect-route:disabled{opacity:.4;cursor:default}.transform-library{padding:18px 20px}.lane-settings{padding:20px;display:grid;grid-template-columns:minmax(160px,1fr) minmax(260px,3fr);gap:24px;background:var(--surface-raised);border-top:1px solid var(--line)}.lane-settings p{font-size:12px;color:var(--muted)}fieldset{border:0;padding:0;min-width:0;margin:0}.empty{padding:20px;color:var(--muted)}.lane-head,.signal-lane{grid-template-columns:minmax(110px,.8fr) minmax(280px,2.5fr) minmax(130px,.9fr)}@media(max-width:850px){.lane-head,.signal-lane{grid-template-columns:150px minmax(220px,1fr) 170px;min-width:640px}.lane-toolbar>span{display:none}.lane-settings{grid-template-columns:1fr}}
</style>
